const { createRequire } = require('node:module')
const { join } = require('node:path')
const { mkdirSync } = require('node:fs')
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require2 = createRequire(join(runtime, 'package.json'))
const { chromium } = require2('playwright')

const url = process.env.URL || 'http://localhost:3002/'
const out = '/tmp/opencode/shots'
mkdirSync(out, { recursive: true })

;(async () => {
  const browser = await chromium.launch({ headless: true })
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
  const errors = []
  page.on('pageerror', e => { errors.push('PAGEERROR: ' + e.message); console.log('PAGEERROR', e.message) })
  page.on('console', m => { if (m.type() === 'error') { errors.push('CONSOLE: ' + m.text()); console.log('CONSOLE', m.text()) } })
  page.on('requestfailed', r => console.log('REQFAIL', r.url(), r.failure()?.errorText))
  await page.goto(url, { waitUntil: 'load' })
  await page.waitForTimeout(1200)
  await page.screenshot({ path: join(out, '01-intro.jpg'), type: 'jpeg', quality: 82 })
  console.log('intro shot')
  const startBtn = page.locator('[aria-label="Start game"]')
  console.log('start count', await startBtn.count())
  if (await startBtn.count()) { await startBtn.first().click(); }
  await page.waitForTimeout(2500)
  await page.screenshot({ path: join(out, '02-game.jpg'), type: 'jpeg', quality: 82 })
  const info = await page.evaluate(() => {
    const g = window.__game
    return {
      money: g.state.money, day: g.state.day, clock: g.state.clock,
      customers: g.state.customers.length, staff: g.state.staff.length,
      phase: g.state.phase, blocked: g.blocked, speed: g.state.speed,
      canvas: (() => { const c = document.getElementById('game'); const r = c.getBoundingClientRect(); return { w: r.width, h: r.height } })()
    }
  })
  console.log('STATE', JSON.stringify(info))
  // accelerate
  await page.evaluate(() => { window.__game.state.speed = 4 })
  await page.waitForTimeout(8000)
  await page.screenshot({ path: join(out, '03-fast.jpg'), type: 'jpeg', quality: 82 })
  const info2 = await page.evaluate(() => {
    const g = window.__game
    return {
      money: g.state.money, clock: g.state.clock, customers: g.state.customers.length,
      queue: g.state.queue.length, served: g.state.stats.served, lost: g.state.stats.lost,
      phase: g.state.phase, dirt: g.state.dirt, rep: g.state.reputation,
      staffStates: g.state.staff.map(s => ({ role: s.role, state: s.state, task: s.task?.type })),
      tables: g.state.tables.map(t => ({ slot: t.slot, unlocked: t.unlocked, dirty: t.dirty, order: t.order?.state || null, customer: !!t.customerId }))
    }
  })
  console.log('STATE2', JSON.stringify(info2, null, 1))
  console.log('ERRORS', errors.length, errors.join('\n'))
  await browser.close()
})().catch(e => { console.error(e); process.exit(1) })

