const { createRequire } = require('node:module')
const { join } = require('node:path')
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require2 = createRequire(join(runtime, 'package.json'))
const { chromium } = require2('playwright')

;(async () => {
  const browser = await chromium.launch({ headless: true })
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
  page.on('pageerror', e => console.log('PAGEERROR', e.message))
  page.on('console', m => console.log('CONSOLE', m.type(), m.text()))
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' })
  await page.waitForTimeout(500)
  const diag = await page.evaluate(() => {
    const tb = document.querySelector('.topbar')
    const cs = getComputedStyle(tb)
    return {
      sheets: [...document.styleSheets].map(s => ({ href: s.href, rules: (() => { try { return s.cssRules.length } catch (e) { return 'ERR ' + e.message } })() })),
      topbar: { display: cs.display, background: cs.backgroundImage, color: cs.color, height: cs.height },
      body: { bg: getComputedStyle(document.body).backgroundColor, color: getComputedStyle(document.body).color },
      intro: !!document.querySelector('.modal.intro'),
      linkHref: document.querySelector('link[rel=stylesheet]')?.href,
      html: document.documentElement.outerHTML.length
    }
  })
  console.log(JSON.stringify(diag, null, 1))
  await page.screenshot({ path: '/tmp/opencode/shots/diag-intro.jpg', type: 'jpeg', quality: 80 })
  await page.evaluate(() => document.querySelector('[data-act="start"]').click())
  await page.waitForTimeout(600)
  const diag2 = await page.evaluate(() => {
    const tb = document.querySelector('.topbar')
    const cs = getComputedStyle(tb)
    return {
      sheets: [...document.styleSheets].map(s => ({ href: s.href, rules: (() => { try { return s.cssRules.length } catch (e) { return 'ERR' } })() })),
      topbar: { display: cs.display, background: cs.backgroundImage, color: cs.color, height: cs.height },
      body: { bg: getComputedStyle(document.body).backgroundColor, color: getComputedStyle(document.body).color },
      modal: document.getElementById('modal-root').innerHTML,
      blocked: window.__game.blocked
    }
  })
  console.log(JSON.stringify(diag2, null, 1))
  await page.screenshot({ path: '/tmp/opencode/shots/diag-game.jpg', type: 'jpeg', quality: 80 })
  await browser.close()
})().catch(e => { console.error(e); process.exit(1) })

