const { mkdirSync } = require('node:fs')
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require2 = createRequire(join(runtime, 'package.json'))
const { chromium } = require2('playwright')

const url = process.env.URL || 'http://localhost:3002/'
const out = '/tmp/opencode/shots'
mkdirSync(out, { recursive: true })

;(async () => {
  const browser = await chromium.launch({ headless: true })
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
  const errors = []
  page.on('pageerror', e => { errors.push('PAGEERROR: ' + e.message); console.log('PAGEERROR', e.message) })
  page.on('console', m => { if (m.type() === 'error') { errors.push('CONSOLE: ' + m.text()); console.log('CONSOLE', m.text()) } })
  page.on('requestfailed', r => console.log('REQFAIL', r.url(), r.failure()?.errorText))
  await page.goto(url, { waitUntil: 'load' })
  await page.waitForTimeout(800)
  const start = page.locator('[aria-label="Start game"]')
  if (await start.count()) await start.first().click()
  await page.waitForTimeout(600)

  const tabs = ['staff', 'upgrades', 'goals', 'reviews', 'menu']
  for (const t of tabs) {
    await page.click(`[data-tab="${t}"]`)
    await page.waitForTimeout(350)
    await page.screenshot({ path: join(out, `tab-${t}.jpg`), type: 'jpeg', quality: 80 })
  }
  console.log('tabs done')

  // Hire the first affordable candidate
  await page.click('[data-tab="staff"]')
  await page.waitForTimeout(300)
  const hire = page.locator('[data-act="hire"]:not([disabled])').first()
  console.log('hire count', await hire.count())
  if (await hire.count()) { await hire.click(); await page.waitForTimeout(500) }
  const teamSize = await page.evaluate(() => window.__game.state.staff.length)
  console.log('staff after hire', teamSize)
  await page.screenshot({ path: join(out, 'after-hire.jpg'), type: 'jpeg', quality: 80 })

  // Toggle a dish off then on, bump a price
  await page.click('[data-tab="menu"]')
  await page.waitForTimeout(300)
  const toggle = page.locator('[data-act="toggle"]').first()
  const before = await toggle.textContent()
  await toggle.click(); await page.waitForTimeout(200)
  const after = await page.locator('[data-act="toggle"]').first().textContent()
  await page.locator('[data-act="toggle"]').first().click(); await page.waitForTimeout(200)
  console.log('dish toggle', JSON.stringify(before), '->', JSON.stringify(after))
  const priceBtn = page.locator('[data-act="price+"]').first()
  const priceBefore = await page.evaluate(() => window.__game.state.menu.bruschetta.price)
  await priceBtn.click(); await page.waitForTimeout(150)
  const priceAfter = await page.evaluate(() => window.__game.state.menu.bruschetta.price)
  console.log('price', priceBefore, '->', priceAfter)

  // Speed 4 and run to end of day
  await page.click('[data-speed="4"]')
  await page.evaluate(() => { window.__game.state.clock = 22 * 60 + 40 })
  await page.waitForTimeout(1500)
  await page.screenshot({ path: join(out, 'report.jpg'), type: 'jpeg', quality: 82 })
  const phase = await page.evaluate(() => window.__game.state.phase)
  console.log('phase after fast forward', phase)
  const modalVisible = await page.locator('.modal').count()
  console.log('report modal count', modalVisible)
  if (phase === 'report') {
    await page.click('[data-act="next-day"]')
    await page.waitForTimeout(600)
    const st = await page.evaluate(() => ({ day: window.__game.state.day, phase: window.__game.state.phase, money: window.__game.state.money, pending: window.__game.state.pending?.type }))
    console.log('after next day', JSON.stringify(st))
    await page.screenshot({ path: join(out, 'day2.jpg'), type: 'jpeg', quality: 82 })
    // close event modal if present
    const ok = page.locator('[data-act="ok"]')
    if (await ok.count()) { await ok.first().click(); await page.waitForTimeout(300) }
  }

  // Pause / resume
  await page.click('#btn-pause')
  const paused = await page.evaluate(() => window.__game.state.speed)
  await page.click('#btn-pause')
  const resumed = await page.evaluate(() => window.__game.state.speed)
  console.log('pause speed', paused, 'resume', resumed)

  // Help modal
  await page.click('#btn-help')
  await page.waitForTimeout(300)
  console.log('help modal', await page.locator('.modal').count())
  await page.screenshot({ path: join(out, 'help.jpg'), type: 'jpeg', quality: 80 })
  await page.click('[data-close]')
  await page.waitForTimeout(200)

  // Persistence: reload
  const beforeReload = await page.evaluate(() => ({ day: window.__game.state.day, money: window.__game.state.money, staff: window.__game.state.staff.length }))
  await page.reload({ waitUntil: 'load' })
  await page.waitForTimeout(900)
  const afterReload = await page.evaluate(() => ({ day: window.__game.state.day, money: window.__game.state.money, staff: window.__game.state.staff.length }))
  console.log('persist before', JSON.stringify(beforeReload), 'after', JSON.stringify(afterReload))

  // Mobile viewport
  await page.setViewportSize({ width: 390, height: 844 })
  await page.waitForTimeout(500)
  await page.screenshot({ path: join(out, 'mobile.jpg'), type: 'jpeg', quality: 80 })
  const overflow = await page.evaluate(() => ({ sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth, sh: document.documentElement.scrollHeight, ch: document.documentElement.clientHeight }))
  console.log('mobile overflow', JSON.stringify(overflow))

  console.log('ERRORS', errors.length, errors.join('\n'))
  await browser.close()
})().catch(e => { console.error(e); process.exit(1) })

