const { createRequire } = require('node:module')
const { join } = require('node:path')
const { mkdirSync } = require('node:fs')
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require2 = createRequire(join(runtime, 'package.json'))
const { chromium } = require2('playwright')

const url = process.env.URL || 'http://localhost:3002/'
const out = '/tmp/opencode/shots'
mkdirSync(out, { recursive: true })

;(async () => {
  const browser = await chromium.launch({ headless: true })
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
  const errors = []
  page.on('pageerror', e => { errors.push('PAGEERROR: ' + e.message); console.log('PAGEERROR', e.message) })
  page.on('console', m => { if (m.type() === 'error') { errors.push('CONSOLE: ' + m.text()); console.log('CONSOLE', m.text()) } })
  page.on('requestfailed', r => console.log('REQFAIL', r.url(), r.failure()?.errorText))
  await page.goto(url, { waitUntil: 'load' })
  await page.waitForTimeout(700)
  // fresh save
  await page.evaluate(() => { localStorage.clear(); location.reload() })
  await page.waitForTimeout(900)
  const start = page.locator('[aria-label="Start game"]')
  if (await start.count()) await start.first().click()
  await page.waitForTimeout(600)

  const newDayHiddenPlaying = await page.evaluate(() => document.getElementById('btn-newday').hidden)
  console.log('newday hidden while playing:', newDayHiddenPlaying)
  await page.screenshot({ path: join(out, 'fresh-start.jpg'), type: 'jpeg', quality: 82 })

  // fast forward to close
  await page.click('[data-speed="4"]')
  await page.evaluate(() => { window.__game.state.clock = 22 * 60 + 55 })
  await page.waitForSelector('.modal', { timeout: 15000 })
  await page.waitForTimeout(500)
  await page.screenshot({ path: join(out, 'report.jpg'), type: 'jpeg', quality: 84 })
  const reportInfo = await page.evaluate(() => ({
    phase: window.__game.state.phase,
    report: window.__game.state.report && { net: window.__game.state.report.net, served: window.__game.state.report.served, lost: window.__game.state.report.lost },
    modalText: document.querySelector('.modal h2')?.textContent,
    newDayHidden: document.getElementById('btn-newday').hidden,
    newDayText: document.getElementById('btn-newday').textContent
  }))
  console.log('REPORT', JSON.stringify(reportInfo))

  // advance day
  await page.click('[data-act="next-day"]')
  await page.waitForTimeout(800)
  const day2 = await page.evaluate(() => ({ day: window.__game.state.day, phase: window.__game.state.phase, pending: window.__game.state.pending?.type, newDayHidden: document.getElementById('btn-newday').hidden }))
  console.log('DAY2', JSON.stringify(day2))
  await page.screenshot({ path: join(out, 'day2.jpg'), type: 'jpeg', quality: 82 })
  // close event modal if present
  const ok = page.locator('[data-act="ok"]')
  if (await ok.count()) { await ok.first().click(); await page.waitForTimeout(400) }
  console.log('after event close, modal count', await page.locator('.modal').count())

  // pause + help
  await page.click('#btn-pause')
  const paused = await page.evaluate(() => window.__game.state.speed)
  await page.click('#btn-pause')
  const resumed = await page.evaluate(() => window.__game.state.speed)
  console.log('pause/resume', paused, resumed)
  await page.click('#btn-help')
  await page.waitForTimeout(400)
  await page.screenshot({ path: join(out, 'help.jpg'), type: 'jpeg', quality: 82 })
  const helpTitle = await page.locator('.modal h2').first().textContent().catch(() => null)
  console.log('help title', helpTitle)
  await page.click('[data-close]')
  await page.waitForTimeout(250)

  // mobile
  await page.setViewportSize({ width: 390, height: 844 })
  await page.waitForTimeout(600)
  await page.screenshot({ path: join(out, 'mobile.jpg'), type: 'jpeg', quality: 82 })
  const overflow = await page.evaluate(() => ({ sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth, sh: document.documentElement.scrollHeight, ch: document.documentElement.clientHeight }))
  console.log('mobile overflow', JSON.stringify(overflow))
  // switch tab on mobile
  await page.click('[data-tab="staff"]')
  await page.waitForTimeout(400)
  await page.screenshot({ path: join(out, 'mobile-staff.jpg'), type: 'jpeg', quality: 82 })

  // persistence
  await page.setViewportSize({ width: 1280, height: 800 })
  const beforeReload = await page.evaluate(() => ({ day: window.__game.state.day, money: window.__game.state.money }))
  await page.reload({ waitUntil: 'load' })
  await page.waitForTimeout(900)
  const afterReload = await page.evaluate(() => ({ day: window.__game.state.day, money: window.__game.state.money, phase: window.__game.state.phase }))
  console.log('persist', JSON.stringify(beforeReload), '->', JSON.stringify(afterReload))

  console.log('ERRORS', errors.length, errors.join('\n'))
  await browser.close()
})().catch(e => { console.error(e); process.exit(1) })

