const { createRequire } = require('node:module')
const { join } = require('node:path')
const { mkdirSync } = require('node:fs')
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require2 = createRequire(join(runtime, 'package.json'))
const { chromium } = require2('playwright')

const url = process.env.URL || 'http://localhost:3002/'
const out = '/tmp/opencode/shots'
mkdirSync(out, { recursive: true })

async function worldToClient(page, wx, wy) {
  return page.evaluate(([wx, wy]) => {
    const c = document.getElementById('game')
    const r = c.getBoundingClientRect()
    const scale = Math.min(r.width / 960, r.height / 600)
    const ox = r.left + (r.width - 960 * scale) / 2
    const oy = r.top + (r.height - 600 * scale) / 2
    return { x: ox + wx * scale, y: oy + wy * scale }
  }, [wx, wy])
}

;(async () => {
  const browser = await chromium.launch({ headless: true })
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
  const errors = []
  page.on('pageerror', e => { errors.push('PAGEERROR: ' + e.message); console.log('PAGEERROR', e.message) })
  page.on('console', m => { if (m.type() === 'error') { errors.push('CONSOLE: ' + m.text()); console.log('CONSOLE', m.text()) } })
  await page.goto(url, { waitUntil: 'load' })
  await page.waitForTimeout(600)
  await page.evaluate(() => { localStorage.clear(); location.reload() })
  await page.waitForTimeout(900)
  await page.screenshot({ path: join(out, 'intro-fresh.jpg'), type: 'jpeg', quality: 84 })
  const introText = await page.evaluate(() => document.querySelector('.modal')?.innerText.slice(0, 200))
  console.log('INTRO', JSON.stringify(introText))
  const start = page.locator('[aria-label="Start game"]')
  if (await start.count()) await start.first().click()
  await page.waitForTimeout(500)

  // Run a chunk of a realistic day
  await page.click('[data-speed="4"]')
  await page.evaluate(() => { window.__game.state.clock = 11 * 60 + 30 })
  await page.waitForTimeout(16000)
  const mid = await page.evaluate(() => ({
    clock: Math.round(window.__game.state.clock), money: Math.round(window.__game.state.money),
    served: window.__game.state.stats.served, lost: window.__game.state.stats.lost,
    customers: window.__game.state.customers.length, queue: window.__game.state.queue.length,
    revenue: Math.round(window.__game.state.stats.revenue), rep: +window.__game.state.reputation.toFixed(2),
    reviews: window.__game.state.reviews.length, level: window.__game.state.level,
    dishes: window.__game.state.dishesUnlocked.length
  }))
  console.log('MIDDAY', JSON.stringify(mid))
  await page.screenshot({ path: join(out, 'midday.jpg'), type: 'jpeg', quality: 84 })

  // Buy first affordable upgrade
  await page.click('[data-tab="upgrades"]')
  await page.waitForTimeout(400)
  const up = page.locator('[data-act="buy-up"]:not([disabled])').first()
  const upName = await up.count() ? await up.evaluate(el => el.closest('.up-card')?.querySelector('b')?.textContent) : null
  if (await up.count()) { await up.click(); await page.waitForTimeout(400) }
  console.log('UPGRADE bought', JSON.stringify(upName))
  await page.screenshot({ path: join(out, 'upgrades-after.jpg'), type: 'jpeg', quality: 82 })

  // Canvas interaction: dirty a table then click to clean
  await page.evaluate(() => {
    const g = window.__game
    const t = g.state.tables.find(t => t.unlocked && !t.customerId)
    t.dirty = true
    window.__testTable = t.slot
  })
  await page.waitForTimeout(200)
  const slot = await page.evaluate(() => window.__testTable)
  const slots = await page.evaluate(() => window.__TABLES || null)
  const coords = await page.evaluate((slot) => {
    // TABLE_SLOTS duplicated for test mapping
    const T = [[150,330],[390,330],[630,330],[870,330],[150,465],[390,465],[630,465],[870,465]]
    const [wx, wy] = T[slot]
    const c = document.getElementById('game'); const r = c.getBoundingClientRect()
    const scale = Math.min(r.width / 960, r.height / 600)
    const ox = r.left + (r.width - 960 * scale) / 2
    const oy = r.top + (r.height - 600 * scale) / 2
    return { x: ox + wx * scale, y: oy + wy * scale }
