  // Clean floor button
  const dirtBefore = await page.evaluate(() => Math.round(window.__game.state.dirt))
  await page.click('#btn-clean')
  await page.waitForTimeout(300)
  const dirtAfter = await page.evaluate(() => Math.round(window.__game.state.dirt))
