  // Finish day
  await page.evaluate(() => { window.__game.state.clock = 22 * 60 + 55 })
  await page.waitForSelector('.modal', { timeout: 20000 })
  await page.waitForTimeout(400)
  const rep = await page.evaluate(() => ({
    phase: window.__game.state.phase,
    report: window.__game.state.report && {
      net: Math.round(window.__game.state.report.net), revenue: Math.round(window.__game.state.report.revenue),
