  await page.click('[data-act="next-day"]')
  await page.waitForTimeout(700)
  const ok = page.locator('[data-act="ok"]')
  if (await ok.count()) { await ok.first().click(); await page.waitForTimeout(300) }
  const day3 = await page.evaluate(() => ({ day: window.__game.state.day, phase: window.__game.state.phase, staff: window.__game.state.staff.length, candidates: window.__game.state.candidates.length }))
