const { createRequire } = require('node:module')
const { join } = require('node:path')
const { mkdirSync } = require('node:fs')
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require2 = createRequire(join(runtime, 'package.json'))
const { chromium } = require2('playwright')

const url = process.env.URL || 'http://localhost:3002/'
const out = '/tmp/opencode/shots'
mkdirSync(out, { recursive: true })

;(async () => {
  const browser = await chromium.launch({ headless: true })
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
  const errors = []
  page.on('pageerror', e => { errors.push('PAGEERROR: ' + e.message); console.log('PAGEERROR', e.message) })
  page.on('console', m => { if (m.type() === 'error') { errors.push('CONSOLE: ' + m.text()); console.log('CONSOLE', m.text()) } })
  await page.goto(url, { waitUntil: 'load' })
  await page.waitForTimeout(600)
  await page.evaluate(() => { localStorage.clear(); location.reload() })
  await page.waitForTimeout(900)
  const start = page.locator('[aria-label="Start game"]')
  if (await start.count()) await start.first().click()
  await page.waitForTimeout(500)
  await page.click('[data-speed="4"]')

  const t0 = Date.now()
  let lastLog = 0
  while (Date.now() - t0 < 95000) {
    await page.waitForTimeout(400)
    const st = await page.evaluate(() => {
      const g = window.__game
      const modal = !!document.querySelector('.modal')
      const hasOk = !!document.querySelector('[data-act="ok"]')
      const report = !!document.querySelector('[data-act="next-day"]')
      return {
        phase: g.state.phase, clock: Math.round(g.state.clock), day: g.state.day,
        money: Math.round(g.state.money), served: g.state.stats.served, lost: g.state.stats.lost,
        rep: +g.state.reputation.toFixed(2), level: g.state.level, modal, hasOk, report,
        queue: g.state.queue.length, customers: g.state.customers.length,
        tables: g.state.tables.filter(t => t.unlocked).length,
        dirty: g.state.tables.filter(t => t.dirty).length
      }
    })
    if (st.phase === 'report') {
      console.log('REPORT_REACHED', JSON.stringify(st))
      await page.waitForTimeout(400)
      await page.screenshot({ path: join(out, 'full-day-report.jpg'), type: 'jpeg', quality: 84 })
      break
    }
    if (st.modal && st.hasOk) {
      console.log('dismiss modal (level/event)', JSON.stringify(st))
      await page.click('[data-act="ok"]')
      await page.waitForTimeout(250)
    }
    if (Date.now() - lastLog > 8000) {
      lastLog = Date.now()
      console.log('tick', JSON.stringify(st))
    }
  }
  const final = await page.evaluate(() => {
    const g = window.__game
    return {
      phase: g.state.phase,
      report: g.state.report && {
        day: g.state.report.day, net: Math.round(g.state.report.net),
        revenue: Math.round(g.state.report.revenue), tips: Math.round(g.state.report.tips),
        ingredients: Math.round(g.state.report.ingredients), wages: g.state.report.wages,
        rent: g.state.report.rent, served: g.state.report.served, lost: g.state.report.lost,
        avgSat: Math.round(g.state.report.avgSat), stars: +g.state.report.stars.toFixed(2)
      },
