const { createRequire } = require('node:module')
const { join } = require('node:path')
const { mkdirSync } = require('node:fs')
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require2 = createRequire(join(runtime, 'package.json'))
const { chromium } = require2('playwright')

const url = process.env.URL || 'http://localhost:3002/'
const out = '/tmp/opencode/shots'
mkdirSync(out, { recursive: true })

;(async () => {
  const browser = await chromium.launch({ headless: true })
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
  const errors = []
  page.on('pageerror', e => { errors.push('PAGEERROR: ' + e.message); console.log('PAGEERROR', e.message) })
  page.on('console', m => { if (m.type() === 'error') { errors.push('CONSOLE: ' + m.text()); console.log('CONSOLE', m.text()) } })
  await page.goto(url, { waitUntil: 'load' })
  await page.waitForTimeout(600)
  await page.evaluate(() => { localStorage.clear(); location.reload() })
  await page.waitForTimeout(900)
  await page.click('[data-act="start"]')
  await page.waitForTimeout(500)
  console.log('newday hidden', await page.evaluate(() => document.getElementById('btn-newday').hidden))

  // Space while modal open should not change speed
  await page.click('#btn-help')
  await page.waitForTimeout(300)
  const speedBefore = await page.evaluate(() => window.__game.state.speed)
  await page.keyboard.press('Space')
  await page.waitForTimeout(200)
  const speedAfter = await page.evaluate(() => window.__game.state.speed)
  await page.keyboard.press('Escape')
  await page.waitForTimeout(250)
  console.log('modal keyboard speed', speedBefore, '->', speedAfter, 'closed', await page.locator('.modal').count())

  // Dish unlock flow
  await page.evaluate(() => { const g = window.__game; g.state.money = 5000; g.state.level = 2; g.updateHeader?.(true) })
  await page.evaluate(() => window.__ui.updateHeader(true))
  await page.click('[data-tab="menu"]')
  await page.waitForTimeout(300)
  const unlockBtn = page.locator('[data-act="unlock"]:not([disabled])').first()
  const unlockName = await unlockBtn.count() ? await unlockBtn.evaluate(el => el.closest('.dish-card')?.querySelector('.dish-title b')?.textContent) : null
  console.log('unlock available', await unlockBtn.count(), unlockName)
  if (await unlockBtn.count()) { await unlockBtn.click(); await page.waitForTimeout(400) }
  const unlocked = await page.evaluate(() => ({ dishes: window.__game.state.dishesUnlocked, money: Math.round(window.__game.state.money) }))
  console.log('after unlock', JSON.stringify(unlocked))
  await page.screenshot({ path: join(out, 'menu-unlocked.jpg'), type: 'jpeg', quality: 82 })

  // Upgrade flow
  await page.click('[data-tab="upgrades"]')
  await page.waitForTimeout(300)
  const up = page.locator('[data-act="buy-up"]:not([disabled])').first()
  const upBefore = await page.evaluate(() => ({ ...window.__game.state.upgrades }))
  if (await up.count()) { await up.click(); await page.waitForTimeout(400) }
  const upAfter = await page.evaluate(() => ({ ...window.__game.state.upgrades }))
  console.log('upgrade before', JSON.stringify(upBefore), 'after', JSON.stringify(upAfter))

  // Goals tab
  await page.click('[data-tab="goals"]')
  await page.waitForTimeout(300)
  const goals = await page.evaluate(() => ({ done: Object.keys(window.__game.state.objectives), total: document.querySelectorAll('.goal-card').length }))
  console.log('goals', JSON.stringify(goals))
  await page.screenshot({ path: join(out, 'goals-mid.jpg'), type: 'jpeg', quality: 82 })

  // Game over flow
  await page.evaluate(() => { window.__game.state.money = -700; window.__game.state.clock = 22 * 60 + 58; window.__game.state.speed = 4 })
  await page.waitForSelector('[data-act="next-day"]', { timeout: 20000 })
  await page.waitForTimeout(300)
  console.log('report shown, money', await page.evaluate(() => Math.round(window.__game.state.money)))
  await page.click('[data-act="next-day"]')
  await page.waitForTimeout(700)
  const go = await page.evaluate(() => ({ phase: window.__game.state.phase, pending: window.__game.state.pending?.type, modal: document.querySelector('.modal')?.innerText.slice(0, 80) }))
  console.log('GAMEOVER', JSON.stringify(go))
  await page.screenshot({ path: join(out, 'gameover.jpg'), type: 'jpeg', quality: 82 })
  const restart = page.locator('[data-act="restart"]')
  if (await restart.count()) { await restart.click(); await page.waitForTimeout(700) }
  const afterRestart = await page.evaluate(() => ({ day: window.__game.state.day, money: Math.round(window.__game.state.money), phase: window.__game.state.phase, staff: window.__game.state.staff.length, dishes: window.__game.state.dishesUnlocked.length }))
  console.log('AFTER RESTART', JSON.stringify(afterRestart))
  await page.screenshot({ path: join(out, 'restarted.jpg'), type: 'jpeg', quality: 82 })

  console.log('ERRORS', errors.length, errors.join('\n'))
  await browser.close()
})().catch(e => { console.error(e); process.exit(1) })

