  page.on('console', m => { if (m.type() === 'error') { errors.push('CONSOLE: ' + m.text()); console.log('CONSOLE', m.text()) } })
  await page.goto(url, { waitUntil: 'load' })
  await page.waitForTimeout(600)
  await page.evaluate(() => { localStorage.clear(); location.reload() })
  await page.waitForTimeout(900)
  await page.click('[data-act="start"]')
  await page.waitForTimeout(400)

  // Buy next table via canvas click
  await page.evaluate(() => { window.__game.state.money = 5000 })
  const before = await page.evaluate(() => ({ tables: window.__game.state.tablesUnlocked, money: window.__game.state.money, next: window.__game.nextTableSlot() }))
  const slot = before.next
  const coords = await page.evaluate((slot) => {
    const T = [[150,330],[390,330],[630,330],[870,330],[150,465],[390,465],[630,465],[870,465]]
    const [wx, wy] = T[slot]
    const c = document.getElementById('game'); const r = c.getBoundingClientRect()
    const scale = Math.min(r.width / 960, r.height / 600)
    return { x: r.left + (r.width - 960 * scale) / 2 + wx * scale, y: r.top + (r.height - 600 * scale) / 2 + wy * scale }
  }, slot)
  await page.mouse.click(coords.x, coords.y)
  await page.waitForTimeout(400)
  const after = await page.evaluate(() => ({ tables: window.__game.state.tablesUnlocked, money: Math.round(window.__game.state.money) }))
  console.log('BUY TABLE slot', slot, JSON.stringify(before), '->', JSON.stringify(after))

  // Refresh candidates
  await page.click('[data-tab="staff"]')
  await page.waitForTimeout(300)
  const candBefore = await page.evaluate(() => window.__game.state.candidates.map(c => c.name))
  await page.click('[data-act="refresh-cand"]')
  await page.waitForTimeout(400)
  const candAfter = await page.evaluate(() => window.__game.state.candidates.map(c => c.name))
  console.log('REFRESH candidates', JSON.stringify(candBefore), '->', JSON.stringify(candAfter))

  // Fire first staff with confirm
  const staffBefore = await page.evaluate(() => window.__game.state.staff.length)
  await page.locator('[data-act="fire"]').first().click()
  await page.waitForTimeout(300)
  const confirmShown = await page.locator('.modal').count()
  await page.click('[data-act="yes"]')
  await page.waitForTimeout(400)
  const staffAfter = await page.evaluate(() => window.__game.state.staff.length)
  console.log('FIRE confirm', confirmShown, 'staff', staffBefore, '->', staffAfter)

  // Critic event force
  await page.evaluate(() => {
    const g = window.__game
    g.state.event = { id: 'critic', title: 'Crítico à vista', emoji: '⭐', tone: 'warn', critic: true, desc: 'teste' }
    g.state.criticSpawned = false
    g.state.clock = 18 * 60 + 58
    g.state.speed = 4
  })
  await page.waitForTimeout(2500)
  const critic = await page.evaluate(() => ({
    spawned: window.__game.state.criticSpawned,
    criticInRoom: window.__game.state.customers.some(c => c.isCritic),
    clock: Math.round(window.__game.state.clock)
  }))
  console.log('CRITIC', JSON.stringify(critic))

  console.log('ERRORS', errors.length, errors.join('\n'))
  await browser.close()
})().catch(e => { console.error(e); process.exit(1) })

